    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 87-year-old male named Henry requires assistance with 4 ADLs (bathing, dressing, meals, toileting), has mild dementia with no behavioral disturbances, no complex medical needs, no IV therapy, and no daily skilled nursing requirements. He family is exploring long-term residential care options. Which of the following care settings is most appropriate for this patient''s current level of need?', '["Independent living retirement community, which requires residents to manage all ADLs independently without assistance and is therefore not appropriate for this patient", "Inpatient psychiatric hospital, which is appropriate because mild dementia with ADL limitations is classified as a psychiatric emergency requiring inpatient stabilization", "Assisted living facility (ALF), which provides 24-hour supervision, personal care (ADL assistance), meals, housekeeping, and social programming for individuals who need help with ADLs but do not require continuous skilled nursing care", "Acute rehabilitation hospital, which is designed for patients requiring intensive physical and occupational therapy (minimum 3 hours/day) following an acute medical event", "Skilled nursing facility (SNF), which is specifically indicated for patients requiring daily skilled nursing care (wound care, IV medications, complex rehabilitation) and would be over-provision for this patient''s current needs"]'::jsonb, 2, 'Understanding the **continuum of long-term care settings** is critical for USMLE Step 2 CK: | Setting | Key Criteria | | --- | --- | | **Independent Living (IL)** | Fully independent in ADLs; no care provided | | **Assisted Living (ALF)** | ADL assistance, supervision, no continuous skilled nursing needed | | **Memory Care Unit** | ALF-level care + secure environment for dementia/wandering | | **Skilled Nursing Facility (SNF)** | Daily skilled nursing care, post-acute rehabilitation, complex medical needs | | **Long-Term Care (LTC) / Nursing Home** | Permanent placement for those who cannot live at home | | **Acute Rehabilitation** | Intensive therapy ≥3 h/day post-acute event | This patient — needing ADL help, mild dementia, no skilled nursing needs — fits **ALF** criteria. ALFs are primarily **private pay** or **Medicaid** (in some states); Medicare does NOT cover ALF costs. (Ref: Hazzard''s Ch. 17; Current Diagnosis & Treatment: Geriatrics; AGS Geriatrics At Your Fingertips; First Aid Step 2 CK)'),
    (v_topic_id, 'A 83-year-old female named Alice requires assistance with 6 ADLs (bathing, dressing, meals, toileting), has mild dementia with no behavioral disturbances, no complex medical needs, no IV therapy, and no daily skilled nursing requirements. She family is exploring long-term residential care options. Which of the following care settings is most appropriate for this patient''s current level of need?', '["Inpatient psychiatric hospital, which is appropriate because mild dementia with ADL limitations is classified as a psychiatric emergency requiring inpatient stabilization", "Independent living retirement community, which requires residents to manage all ADLs independently without assistance and is therefore not appropriate for this patient", "Skilled nursing facility (SNF), which is specifically indicated for patients requiring daily skilled nursing care (wound care, IV medications, complex rehabilitation) and would be over-provision for this patient''s current needs", "Assisted living facility (ALF), which provides 24-hour supervision, personal care (ADL assistance), meals, housekeeping, and social programming for individuals who need help with ADLs but do not require continuous skilled nursing care", "Acute rehabilitation hospital, which is designed for patients requiring intensive physical and occupational therapy (minimum 3 hours/day) following an acute medical event"]'::jsonb, 3, 'Understanding the **continuum of long-term care settings** is critical for USMLE Step 2 CK: | Setting | Key Criteria | | --- | --- | | **Independent Living (IL)** | Fully independent in ADLs; no care provided | | **Assisted Living (ALF)** | ADL assistance, supervision, no continuous skilled nursing needed | | **Memory Care Unit** | ALF-level care + secure environment for dementia/wandering | | **Skilled Nursing Facility (SNF)** | Daily skilled nursing care, post-acute rehabilitation, complex medical needs | | **Long-Term Care (LTC) / Nursing Home** | Permanent placement for those who cannot live at home | | **Acute Rehabilitation** | Intensive therapy ≥3 h/day post-acute event | This patient — needing ADL help, mild dementia, no skilled nursing needs — fits **ALF** criteria. ALFs are primarily **private pay** or **Medicaid** (in some states); Medicare does NOT cover ALF costs. (Ref: Hazzard''s Ch. 17; Current Diagnosis & Treatment: Geriatrics; AGS Geriatrics At Your Fingertips; First Aid Step 2 CK)'),
